/* Explicit strand connections; independent of legacy destination labels. */
(()=>{
const key='mk-network-inventory-v1';
let data={cables:[],joints:[]};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.cables)&&Array.isArray(saved.joints))data=saved}catch(e){}
const esc=escapeHtml;
const button=document.createElement('button');button.textContent='Cabos e conexões';button.onclick=open;document.querySelector('.toolbar-actions').append(button);
const modal=document.createElement('dialog');modal.style.cssText='background:#0b1914;color:#e3eee8;border:1px solid #32634c;border-radius:16px;width:min(850px,92vw);max-height:85vh;overflow:auto;padding:24px';document.body.append(modal);
const style=document.createElement('style');style.textContent='.network-form{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.network-form label{display:grid;gap:6px;font-size:14px;flex:1;min-width:140px}.network-form input,.network-form select{padding:10px;background:#132b20;color:white;border:1px solid #456451;border-radius:6px;width:100%}.network-form button,dialog button{padding:10px;cursor:pointer}dialog::backdrop{background:#0009}.network-list{width:100%;border-collapse:collapse;font-size:14px}.network-list td,.network-list th{padding:10px;text-align:left;border-bottom:1px solid #31523e}';document.head.append(style);
function save(next){try{localStorage.setItem(key,JSON.stringify(next));data=next;return true}catch(e){say('Não foi possível salvar os cadastros. Exporte um backup antes de fechar.');return false}}
function options(){return data.cables.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} (${c.count} fibras)</option>`).join('')}
function cable(id){return data.cables.find(c=>c.id===id)}
function open(){render();modal.showModal()}
function render(){modal.innerHTML=`<header style="display:flex;justify-content:space-between"><h2>Cabos e conexões</h2><button id="net-close" aria-label="Fechar">×</button></header><p>Cadastro técnico separado dos vínculos antigos. Salvo neste navegador; exporte o backup para transferir a outro dispositivo.</p><form id="net-cable" class="network-form"><label>Nome do cabo<input name="name" required maxlength="100"></label><label>Quantidade de fibras<input name="count" type="number" min="1" max="864" value="24" required></label><label>Ponta A — caixa / DGO / site<input name="a" required maxlength="100"></label><label>Ponta B — caixa / DGO / site<input name="b" required maxlength="100"></label><button>Cadastrar cabo</button></form><table class="network-list"><thead><tr><th>Cabo</th><th>Pontas</th><th>Fibras com conexão</th></tr></thead><tbody>${data.cables.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.a)} ↔ ${esc(c.b)}</td><td>${new Set(data.joints.flatMap(j=>j.a===c.id?[j.fa]:j.b===c.id?[j.fb]:[])).size} / ${c.count}</td></tr>`).join('')||'<tr><td colspan="3">Nenhum cabo cadastrado.</td></tr>'}</tbody></table><h3>Fusão individual</h3><form id="net-joint" class="network-form"><label>Caixa da fusão<input name="box" required maxlength="100"></label><label>Cabo A<select name="a" required>${options()}</select></label><label>Fibra A<input name="fa" type="number" min="1" required></label><label>Cabo B<select name="b" required>${options()}</select></label><label>Fibra B<input name="fb" type="number" min="1" required></label><label>Site atendido (opcional)<input name="site" maxlength="100"></label><button>Adicionar fusão</button></form><table class="network-list"><tbody>${data.joints.map(j=>`<tr><td>${esc(j.box)}</td><td>${esc(cable(j.a).name)} · ${j.fa} ↔ ${esc(cable(j.b).name)} · ${j.fb}</td><td>${esc(j.site||'Sem site informado')}</td><td><button data-remove="${j.id}">Remover</button></td></tr>`).join('')}</tbody></table><h3>Consultar continuidade cadastrada</h3><form id="net-trace" class="network-form"><label>Cabo inicial<select name="cable" required>${options()}</select></label><label>Fibra<input name="fiber" type="number" min="1" required></label><button>Rastrear conexões</button></form><div id="net-result" aria-live="polite"></div><p>Esta consulta segue fusões cadastradas. Ainda não calcula distância no mapa nem confirma presença de sinal.</p><button id="net-export">Exportar backup de cabos e fusões</button>`;
modal.querySelector('#net-close').onclick=()=>modal.close();
const restore=document.createElement('input');restore.type='file';restore.accept='.json';restore.setAttribute('aria-label','Restaurar backup de cabos e fusões');modal.append(document.createElement('hr'),document.createTextNode('Restaurar backup: '),restore);restore.onchange=async()=>{try{const incoming=JSON.parse(await restore.files[0].text());if(incoming.version!==1||!Array.isArray(incoming.cables)||!Array.isArray(incoming.joints))throw Error();const ids=new Set();for(const c of incoming.cables){if(typeof c.id!=='string'||ids.has(c.id)||![c.name,c.a,c.b].every(v=>typeof v==='string'&&v.trim())||!Number.isInteger(c.count)||c.count<1||c.count>864||norm(c.a)===norm(c.b))throw Error();ids.add(c.id)}const checked={cables:incoming.cables,joints:[]};for(const j of incoming.joints){if(typeof j.id!=='string'||typeof j.box!=='string'||(j.site!=null&&typeof j.site!=='string')||checked.joints.some(x=>x.id===j.id))throw Error();validateJoint(checked,j);checked.joints.push(j)}if(confirm('Substituir o cadastro de cabos e fusões pelo backup? O mapa não será alterado.')&&save(checked))render()}catch(e){say('Backup inválido. Nenhum cadastro foi alterado.')}};
modal.querySelector('#net-cable').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),c={id:crypto.randomUUID(),name:f.get('name').trim(),count:Number(f.get('count')),a:f.get('a').trim(),b:f.get('b').trim()};if(!c.name||!c.a||!c.b||norm(c.a)===norm(c.b)||!Number.isInteger(c.count)||c.count<1||c.count>864)return say('Informe duas pontas diferentes e quantidade válida.');if(data.cables.some(x=>norm(x.name)===norm(c.name)))return say('Já existe um cabo com esse nome.');if(save({...data,cables:[...data.cables,c]}))render()};
modal.querySelector('#net-joint').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),j={id:crypto.randomUUID(),box:f.get('box').trim(),a:f.get('a'),b:f.get('b'),fa:Number(f.get('fa')),fb:Number(f.get('fb')),site:f.get('site').trim()};try{validateJoint(data,j)}catch(err){return say(err.message)}if(save({...data,joints:[...data.joints,j]}))render()};
modal.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(confirm('Remover esta fusão?')&&save({...data,joints:data.joints.filter(j=>j.id!==b.dataset.remove)}))render()});
modal.querySelector('#net-trace').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('cable'),fiber=Number(f.get('fiber'));if(!cable(id)||!Number.isInteger(fiber)||fiber<1||fiber>cable(id).count)return say('Fibra fora da capacidade do cabo.');const nodes=trace(data,id,fiber);modal.querySelector('#net-result').innerHTML='<ol>'+nodes.map(n=>`<li>${esc(cable(n.cable).name)} — fibra ${n.fiber}${n.box?' · via '+esc(n.box):''}${n.site?' · '+esc(n.site):''}</li>`).join('')+'</ol><p>Limite das conexões cadastradas alcançado; confira as pontas e fusões restantes.</p>'};
modal.querySelector('#net-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,...data},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='mk-cabos-fusoes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
}
function norm(v){return String(v).trim().toLocaleUpperCase('pt-BR')}
function validateJoint(d,j){if(j.a===j.b)throw Error('Selecione dois cabos diferentes.');for(const [id,f] of [[j.a,j.fa],[j.b,j.fb]]){const c=d.cables.find(c=>c.id===id);if(!c||!Number.isInteger(f)||f<1||f>c.count)throw Error('Fibra fora da capacidade do cabo.');if(![c.a,c.b].some(p=>norm(p)===norm(j.box)))throw Error('A caixa precisa ser uma ponta de ambos os cabos.');if(d.joints.some(x=>norm(x.box)===norm(j.box)&&((x.a===id&&x.fa===f)||(x.b===id&&x.fb===f))))throw Error('Essa fibra já tem fusão nessa caixa.');}}
function trace(d,id,fiber){const queue=[{cable:id,fiber}],seen=new Set(),result=[];while(queue.length){const n=queue.shift(),key=n.cable+':'+n.fiber;if(seen.has(key))continue;seen.add(key);result.push(n);for(const j of d.joints){if(j.a===n.cable&&j.fa===n.fiber)queue.push({cable:j.b,fiber:j.fb,box:j.box,site:j.site});if(j.b===n.cable&&j.fb===n.fiber)queue.push({cable:j.a,fiber:j.fa,box:j.box,site:j.site})}}return result}
})();
